26	/**
27	 * Normaliza nome de produto pra match resiliente: sem acento, lower, espaços
28	 * colapsados, trim. Espelha a normalização de `produtos_master.nome_normalizado`.
29	 */
30	export function normalizeProdutoNome(s: string | null | undefined): string {
31	  return (s || '')
32	    .toLowerCase()
33	    .normalize('NFD')
34	    // Remove diacríticos combinantes (U+0300–U+036F). Escapado de propósito —
35	    // literais combinantes no source são frágeis a re-encoding.
36	    .replace(/[̀-ͯ]/g, '')
37	    .replace(/\s+/g, ' ')
38	    .trim();
39	}
