41	/**
42	 * Acha o item da requisição correspondente a um bip.
43	 *  1) por `produto_master_id` (masterId) — caminho canônico
44	 *  2) fallback por nome normalizado — blinda contra masterId ausente no front
45	 *     (resolução client-side de produtos_master pode falhar; produto_id pode
46	 *     vir null; INSERT realtime chega sem masterId).
47	 * Retorna `null` somente quando o produto realmente não pertence à requisição.
48	 */
49	export function matchBipItem<T extends BipMatchItem>(
50	  items: T[],
51	  scannedPid: number | null | undefined,
52	  scannedNome: string | null | undefined,
53	): T | null {
54	  if (scannedPid != null) {
55	    const byId = items.find((i) => i.masterId != null && i.masterId === scannedPid);
56	    if (byId) return byId;
57	  }
58	  const n = normalizeProdutoNome(scannedNome);
59	  if (n) {
