/**
 * @module pickingBip
 *
 * Helpers puros do fluxo de bip dentro da Separação Digital (PickingBipModal).
 *
 * Extraídos para testabilidade e para tornar a aplicação de cada bip
 * AUTORITATIVA: a quantidade enviada de cada item é acumulada num Map único
 * (fonte de verdade), nunca recomputada a partir de estado de render stale.
 * Isso elimina os dois defeitos observados em produção (req #762, 2026-06-25):
 *   (a) subcontagem — bips concorrentes do mesmo item liam a mesma base e
 *       sobrescreviam (2 bips → quantidade_enviada "1");
 *   (b) bip que não preenche — item casado por `masterId` ausente no front
 *       caía em "não encontrado" e era engolido (fica 0/N, re-bip = "já lido").
 */
import { calcularIncrementoBip } from '@/shared/hooks/useEtiquetaScanner';

export interface BipMatchItem {
  id: number;
  produto_nome: string;
  masterId?: number;
  quantidade_enviada?: string | number | null;
  unidade_medida?: string | null;
  selectedBatches?: Record<string, number>;
}

/**
 * Normaliza nome de produto pra match resiliente: sem acento, lower, espaços
 * colapsados, trim. Espelha a normalização de `produtos_master.nome_normalizado`.
 */
export function normalizeProdutoNome(s: string | null | undefined): string {
  return (s || '')
    .toLowerCase()
    .normalize('NFD')
    // Remove diacríticos combinantes (U+0300–U+036F). Escapado de propósito —
    // literais combinantes no source são frágeis a re-encoding.
    .replace(/[̀-ͯ]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

/**
 * Acha o item da requisição correspondente a um bip.
 *  1) por `produto_master_id` (masterId) — caminho canônico
 *  2) fallback por nome normalizado — blinda contra masterId ausente no front
 *     (resolução client-side de produtos_master pode falhar; produto_id pode
 *     vir null; INSERT realtime chega sem masterId).
 * Retorna `null` somente quando o produto realmente não pertence à requisição.
 */
export function matchBipItem<T extends BipMatchItem>(
  items: T[],
  scannedPid: number | null | undefined,
  scannedNome: string | null | undefined,
): T | null {
  if (scannedPid != null) {
    const byId = items.find((i) => i.masterId != null && i.masterId === scannedPid);
    if (byId) return byId;
  }
  const n = normalizeProdutoNome(scannedNome);
  if (n) {
    const byName = items.find((i) => normalizeProdutoNome(i.produto_nome) === n);
    if (byName) return byName;
  }
  return null;
}

/**
 * Calcula a nova quantidade enviada AUTORITATIVA de um item após um bip.
 *
 * `accum` é o Map fonte-de-verdade (itemId → unidades já enviadas), seedado na
 * abertura do modal a partir de `quantidade_enviada`. A base sai SEMPRE do
 * acumulador quando presente; só cai em `quantidade_enviada` se o item ainda
 * não foi seedado (defensivo). Não muta `accum` — o caller grava após o onApply.
 *
 * Incremento universal (via calcularIncrementoBip):
 *   tipo da etiqueta é container (caixa/saco/pote/…) → +1
 *   senão (granel/un/kg)                              → +quantidade_interna
 */
export function computeNovaQtd(
  accum: Map<number, number>,
  item: BipMatchItem,
  tipoEmbalagemEtiqueta: string | null | undefined,
  qtyInternaEtiqueta: number,
): { base: number; incremento: number; nova: number } {
  const base = accum.has(item.id)
    ? (accum.get(item.id) as number)
    : Number(item.quantidade_enviada || 0) || 0;
  const incremento = calcularIncrementoBip(
    item.unidade_medida,
    tipoEmbalagemEtiqueta,
    qtyInternaEtiqueta,
  );
  return { base, incremento, nova: base + incremento };
}

/**
 * Acumula a quantidade FÍSICA da etiqueta no lote correspondente (imutável —
 * devolve novo objeto). Lote sempre conta unidades reais (qty_interna),
 * independente da unidade do pedido, pra o estoque por lote ficar correto.
 */
export function accumBatches(
  current: Record<string, number> | undefined,
  loteId: string | null | undefined,
  qtyFisica: number,
): Record<string, number> {
  const next: Record<string, number> = { ...(current || {}) };
  if (loteId) next[loteId] = (next[loteId] || 0) + (Number(qtyFisica) || 0);
  return next;
}

