import { describe, it, expect } from 'vitest';
import {
  normalizeProdutoNome,
  matchBipItem,
  computeNovaQtd,
  accumBatches,
  type BipMatchItem,
} from './pickingBip';

describe('normalizeProdutoNome', () => {
  it('remove acento, baixa caixa, colapsa espaços e dá trim', () => {
    expect(normalizeProdutoNome('  CUBA MOUSSE DE MARACUJÁ ')).toBe('cuba mousse de maracuja');
    expect(normalizeProdutoNome('BOLO POTE BANOFFE')).toBe('bolo pote banoffe');
    expect(normalizeProdutoNome('Pão de  Mel')).toBe('pao de mel');
  });

  it('mantém parênteses (não quebra como no .or() do PostgREST)', () => {
    expect(normalizeProdutoNome('CAFÉ(GRÃO)')).toBe('cafe(grao)');
  });

  it('lida com null/undefined', () => {
    expect(normalizeProdutoNome(null)).toBe('');
    expect(normalizeProdutoNome(undefined)).toBe('');
  });
});

describe('matchBipItem', () => {
  const items: BipMatchItem[] = [
    { id: 1, produto_nome: 'BOLO POTE BANOFFE', masterId: 1036 },
    { id: 2, produto_nome: 'BOLO POTE PISTACHE', masterId: 1038 },
    { id: 3, produto_nome: 'CUBA MOUSSE DE MARACUJÁ' }, // masterId AUSENTE (caso do bug)
  ];

  it('casa por masterId (caminho canônico)', () => {
    expect(matchBipItem(items, 1038, 'qualquer')?.id).toBe(2);
  });

  it('cai no fallback por nome normalizado quando masterId não casa', () => {
    // produto existe na req mas o front não resolveu masterId → casa por nome
    expect(matchBipItem(items, 9999, 'cuba mousse de maracuja')?.id).toBe(3);
    expect(matchBipItem(items, null, 'BOLO POTE BANOFFE')?.id).toBe(1);
  });

  it('prioriza masterId sobre nome', () => {
    // pid casa item 1; nome casaria item 2 — id vence
    expect(matchBipItem(items, 1036, 'BOLO POTE PISTACHE')?.id).toBe(1);
  });

  it('retorna null só quando o produto realmente não está na requisição', () => {
    expect(matchBipItem(items, 9999, 'PRODUTO INEXISTENTE')).toBeNull();
  });
});

describe('computeNovaQtd — acumulador autoritativo (fix da subcontagem)', () => {
  const item: BipMatchItem = { id: 1, produto_nome: 'CUBA COOKIE', masterId: 1057, unidade_medida: 'cx' };

  it('container (caixa/pote) soma +1 por bip', () => {
    const accum = new Map<number, number>([[1, 0]]);
    const r = computeNovaQtd(accum, item, 'caixa', 12);
    expect(r).toEqual({ base: 0, incremento: 1, nova: 1 });
  });

  it('dois bips consecutivos do MESMO item acumulam (2, não 1)', () => {
    const accum = new Map<number, number>([[1, 0]]);
    const r1 = computeNovaQtd(accum, item, 'caixa', 12);
    accum.set(item.id, r1.nova); // caller grava após onApply
    const r2 = computeNovaQtd(accum, item, 'caixa', 12);
    expect(r1.nova).toBe(1);
    expect(r2.nova).toBe(2); // <- antes do fix isto dava 1 (lost update)
  });

  it('granel/sem tipo soma a quantidade física interna', () => {
    const granel: BipMatchItem = { id: 5, produto_nome: 'VEGABALL KG', unidade_medida: 'kg' };
    const accum = new Map<number, number>([[5, 0]]);
    expect(computeNovaQtd(accum, granel, null, 5).nova).toBe(5);
  });

  it('respeita preenchimento manual prévio (base = quantidade_enviada quando não seedado)', () => {
    const itemComEnviada: BipMatchItem = { id: 9, produto_nome: 'X', masterId: 1, unidade_medida: 'cx', quantidade_enviada: '3' };
    const accum = new Map<number, number>(); // item ainda não seedado
    expect(computeNovaQtd(accum, itemComEnviada, 'caixa', 1).nova).toBe(4);
  });
});

describe('accumBatches', () => {
  it('adiciona qty física no lote', () => {
    expect(accumBatches(undefined, 'lote-a', 12)).toEqual({ 'lote-a': 12 });
  });

  it('acumula no mesmo lote sem mutar o original', () => {
    const cur = { 'lote-a': 12 };
    const next = accumBatches(cur, 'lote-a', 5);
    expect(next).toEqual({ 'lote-a': 17 });
    expect(cur).toEqual({ 'lote-a': 12 }); // imutável
  });

  it('ignora lote nulo', () => {
    expect(accumBatches({ 'lote-a': 12 }, null, 5)).toEqual({ 'lote-a': 12 });
  });
});

