1	/**
2	 * Modal de bip dentro da Separação Digital (PaginaPicking).
3	 *
4	 * Operador bipa cada caixa que vai entrar no pedido. Para cada UID:
5	 *  1. Pré-fetch etiquetas_qr pra saber quantidade_interna (não muta status)
6	 *  2. Se nova_qtd > pedido → AlertDialog de excesso (CTO: aceita com confirmação)
7	 *  3. RPC bipar_etiqueta(uid,'separacao', {requisicao_id}) — valida + transição
8	 *  4. Acha item por produto_master_id
9	 *  5. Incrementa quantidade_enviada do item (qty da embalagem do QR)
10	 *  6. Reaproveita selectedBatches com lote do QR
11	 *  7. Chama onBip — PaginaPicking persiste via updateItemEnviada existente
12	 *
13	 * UI mostra progresso por item: caixas bipadas + un acumuladas lado-a-lado.
14	 *
15	 * Fix A (2026-06-19): onPointerDownOutside + onInteractOutside previnem que
16	 *   AlertDialog aninhado (excesso) feche o Dialog pai.
17	 * Fix B2 (2026-06-19): transferência automática quando etiqueta está separada em
18	 *   OUTRA requisição (sem diálogo de confirmação). Se separada NA MESMA → bloqueia.
19	 */
20	import { useEffect, useMemo, useRef, useState } from "react";
21	import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
22	import { Button } from "@/shared/ui/button";
23	import { ScrollArea } from "@/shared/ui/scroll-area";
24	import {
25	  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
26	  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
27	} from "@/shared/ui/alert-dialog";
28	import {
29	  ArrowLeft, Bluetooth, Camera, ScanBarcode, Package, CheckCircle2, AlertTriangle, Boxes,
30	} from "lucide-react";
31	import { toast } from "sonner";
32	import { cn } from "@/shared/lib/utils";
33	import { supabase } from "@/integrations/supabase/client";
34	import {
35	  useEtiquetaScanner,
36	  playSuccessSound,
37	  playErrorSound,
38	  playWarningSound,
39	  formatBipError,
40	  calcularIncrementoBip,
41	  type ScannedPayload,
42	} from "@/shared/hooks/useEtiquetaScanner";
43	import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";
44	import { matchBipItem, computeNovaQtd, accumBatches } from "@/features/requisicoes/lib/pickingBip";
45	
46	export interface PickingBipItem {
47	  id: number;
48	  produto_nome: string;
49	  masterId?: number;
50	  quantidade: number;
51	  quantidade_enviada?: string;
52	  coletado: boolean;
53	  selectedBatches?: Record<string, number>;
54	  availableBatches?: Array<{ id: string; lote_id: string; quantidade: number; lotes: { id: string; codigo: string } }>;
55	  // Unidade do PEDIDO. Decide se cada bip soma +1 (caixa) ou +quantidade_interna (kg, un).
56	  unidade_medida?: string | null;
57	}
58	
59	
60	export interface BipApplied {
61	  itemId: number;
62	  produtoNome: string;
63	  uid: string;
64	  qty: number;
65	  /** Unidade INTERNA da etiqueta (un, kg, g). Em "Caixa com 12 un" = "un". */
66	  embalagem: string | null;
67	  /** Tipo do CONTAINER físico (caixa, saco, balde…). Usado na UI ao invés de embalagem. */
68	  tipoEmbalagem: string | null;
69	  /** Qty INTERNA da etiqueta (12, 5, etc). Pra mostrar "1 caixa (12 un)". */
70	  qtyInterna: number;
71	  loteId: string | null;
72	  bipadoAt: number;
73	}
74	
75	interface ExcessoState {
76	  open: boolean;
77	  produtoNome: string;
78	  pedidoQtd: number;
79	  jaEnviado: number;
80	  etiquetaQtd: number;
81	  sobra: number;
82	  resolve?: (ok: boolean) => void;
83	}
84	
85	interface Props {
86	  isOpen: boolean;
87	  onClose: () => void;
