/**
 * Modal de bip dentro da Separação Digital (PaginaPicking).
 *
 * Operador bipa cada caixa que vai entrar no pedido. Para cada UID:
 *  1. Pré-fetch etiquetas_qr pra saber quantidade_interna (não muta status)
 *  2. Se nova_qtd > pedido → AlertDialog de excesso (CTO: aceita com confirmação)
 *  3. RPC bipar_etiqueta(uid,'separacao', {requisicao_id}) — valida + transição
 *  4. Acha item por produto_master_id
 *  5. Incrementa quantidade_enviada do item (qty da embalagem do QR)
 *  6. Reaproveita selectedBatches com lote do QR
 *  7. Chama onBip — PaginaPicking persiste via updateItemEnviada existente
 *
 * UI mostra progresso por item: caixas bipadas + un acumuladas lado-a-lado.
 *
 * Fix A (2026-06-19): onPointerDownOutside + onInteractOutside previnem que
 *   AlertDialog aninhado (excesso) feche o Dialog pai.
 * Fix B2 (2026-06-19): transferência automática quando etiqueta está separada em
 *   OUTRA requisição (sem diálogo de confirmação). Se separada NA MESMA → bloqueia.
 */
import { useEffect, useMemo, useRef, useState } from "react";
import { Dialog, DialogContent, DialogTitle } from "@/shared/ui/dialog";
import { Button } from "@/shared/ui/button";
import { ScrollArea } from "@/shared/ui/scroll-area";
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from "@/shared/ui/alert-dialog";
import {
  ArrowLeft, Bluetooth, Camera, ScanBarcode, Package, CheckCircle2, AlertTriangle, Boxes,
} from "lucide-react";
import { toast } from "sonner";
import { cn } from "@/shared/lib/utils";
import { supabase } from "@/integrations/supabase/client";
import {
  useEtiquetaScanner,
  playSuccessSound,
  playErrorSound,
  playWarningSound,
  formatBipError,
  calcularIncrementoBip,
  type ScannedPayload,
} from "@/shared/hooks/useEtiquetaScanner";
import { CameraScannerStatus } from "@/features/logistica/ui/CameraScannerStatus";
import { matchBipItem, computeNovaQtd, accumBatches } from "@/features/requisicoes/lib/pickingBip";

export interface PickingBipItem {
  id: number;
  produto_nome: string;
  masterId?: number;
  quantidade: number;
  quantidade_enviada?: string;
  coletado: boolean;
  selectedBatches?: Record<string, number>;
  availableBatches?: Array<{ id: string; lote_id: string; quantidade: number; lotes: { id: string; codigo: string } }>;
  // Unidade do PEDIDO. Decide se cada bip soma +1 (caixa) ou +quantidade_interna (kg, un).
  unidade_medida?: string | null;
}


export interface BipApplied {
  itemId: number;
  produtoNome: string;
  uid: string;
  qty: number;
  /** Unidade INTERNA da etiqueta (un, kg, g). Em "Caixa com 12 un" = "un". */
  embalagem: string | null;
  /** Tipo do CONTAINER físico (caixa, saco, balde…). Usado na UI ao invés de embalagem. */
  tipoEmbalagem: string | null;
  /** Qty INTERNA da etiqueta (12, 5, etc). Pra mostrar "1 caixa (12 un)". */
  qtyInterna: number;
  loteId: string | null;
  bipadoAt: number;
}

interface ExcessoState {
  open: boolean;
  produtoNome: string;
  pedidoQtd: number;
  jaEnviado: number;
  etiquetaQtd: number;
  sobra: number;
  resolve?: (ok: boolean) => void;
}

interface Props {
  isOpen: boolean;
  onClose: () => void;
  items: PickingBipItem[];
  requisicaoId: string | number;
  onApply: (itemId: number, novaQuantidade: string, batches?: Record<string, number>) => Promise<void> | void;
  defaultMode?: "bluetooth" | "camera";
}

export function PickingBipModal({ isOpen, onClose, items, requisicaoId, onApply, defaultMode = "bluetooth" }: Props) {
  const [aplicados, setAplicados] = useState<BipApplied[]>([]);
  const uidsLidosRef = useRef<Set<string>>(new Set());
  // Acumulador AUTORITATIVO da quantidade enviada por item (itemId → un).
  // Fonte de verdade — seedado na abertura. Cada bip incrementa aqui de forma
  // síncrona dentro do mutex serial, nunca recomputa de estado de render stale.
  const enviadaAcumRef = useRef<Map<number, number>>(new Map());
  // Acumulador autoritativo dos lotes físicos por item (itemId → {loteId: un}).
  const batchesAcumRef = useRef<Map<number, Record<string, number>>>(new Map());
  // Mutex serial: encadeia cada bip pra que seu read-modify-write seja atômico.
  // Sem isso, bips concorrentes do mesmo item leem a mesma base e sobrescrevem
  // (subcontagem: 2 bips → enviada "1"). Eventos de scan vêm em ticks separados,
  // então a reatribuição síncrona de processingRef.current serializa de fato.
  const processingRef = useRef<Promise<void>>(Promise.resolve());
  const [excesso, setExcesso] = useState<ExcessoState>({
    open: false, produtoNome: "", pedidoQtd: 0, jaEnviado: 0, etiquetaQtd: 0, sobra: 0,
  });

  // Seed dos acumuladores ao ABRIR o modal — uma vez por abertura. Depende só de
  // `isOpen` (não de `items`, que vira novo array a cada render e zeraria o
  // progresso a cada bip). No momento da abertura, `items` reflete o que já está
  // em quantidade_enviada (inclui preenchimento manual prévio).
  useEffect(() => {
    if (!isOpen) return;
    const enviada = new Map<number, number>();
    const batches = new Map<number, Record<string, number>>();
    items.forEach((i) => {
      enviada.set(i.id, Number(i.quantidade_enviada || 0) || 0);
      if (i.selectedBatches) batches.set(i.id, { ...i.selectedBatches });
    });
    enviadaAcumRef.current = enviada;
    batchesAcumRef.current = batches;
    uidsLidosRef.current = new Set();
    processingRef.current = Promise.resolve();
    setAplicados([]);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [isOpen]);

  // Transfere separação de outra requisição para esta — chamada automaticamente
  // quando o operador bipa uma etiqueta já separada em REQ DIFERENTE da atual.
  // Parâmetros explícitos em vez de depender de estado (reseparirDialog removido).
  const executarTransferencia = async (uid: string, produtoNome: string, payload: ScannedPayload) => {
    try {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta_reseparar", {
        p_uid: uid,
        p_contexto: {
          referencia_tipo: "requisicao",
          referencia_id: String(requisicaoId),
          payload,
        },
      });
      const rpc = rpcRaw as {
        ok: boolean;
        erro?: string;
        etiqueta?: {
          produto_master_id: number;
          produto_nome_snapshot?: string | null;
          lote_id?: string | null;
          quantidade_interna?: number;
          embalagem_nome?: string | null;
          tipo_embalagem?: string | null;
        };
      } | null;
      if (rpcErr || !rpc?.ok || !rpc.etiqueta) {
        playErrorSound();
        toast.error(rpc?.erro || rpcErr?.message || "Falha ao transferir separação");
        return;
      }

      const scannedPid = rpc.etiqueta.produto_master_id;
      const qtyEtiquetaReal = Number(rpc.etiqueta.quantidade_interna ?? payload.qty ?? 1);
      const scannedLote = rpc.etiqueta.lote_id ?? null;
      const scannedEmb = rpc.etiqueta.embalagem_nome ?? null;
      const scannedTipoEmb = rpc.etiqueta.tipo_embalagem ?? payload.tipo ?? null;
      const scannedNome = rpc.etiqueta.produto_nome_snapshot || produtoNome;

      const targetReal = matchBipItem(items, scannedPid, scannedNome);
      if (!targetReal) {
        uidsLidosRef.current.add(uid);
        toast.warning(`${scannedNome} transferido mas NÃO está na lista — registrado como extra`);
        return;
      }
      const { incremento: scannedQty, nova: novaQtdNum } = computeNovaQtd(
        enviadaAcumRef.current, targetReal, scannedTipoEmb, qtyEtiquetaReal,
      );
      enviadaAcumRef.current.set(targetReal.id, novaQtdNum);
      const batchesNovo = accumBatches(batchesAcumRef.current.get(targetReal.id), scannedLote, qtyEtiquetaReal);
      batchesAcumRef.current.set(targetReal.id, batchesNovo);

      await onApply(targetReal.id, String(novaQtdNum), Object.keys(batchesNovo).length ? batchesNovo : undefined);
      playSuccessSound();
      if (navigator.vibrate) navigator.vibrate(100);
      toast.success(`Separação transferida pra esta requisição: ${scannedNome}`);
      setAplicados((prev) => [
        {
          itemId: targetReal.id, produtoNome: targetReal.produto_nome,
          uid, qty: scannedQty,
          embalagem: scannedEmb, tipoEmbalagem: scannedTipoEmb,
          qtyInterna: qtyEtiquetaReal, loteId: scannedLote, bipadoAt: Date.now(),
        },
        ...prev,
      ]);
      uidsLidosRef.current.add(uid);
    } catch (e) {
      playErrorSound();
      toast.error(`Erro: ${(e as Error).message}`);
    }
  };

  const handleBipInner = async (payload: ScannedPayload) => {
    if (!payload.uid) {
      playErrorSound();
      toast.error("Etiqueta sem UID — não rastreável");
      return;
    }
    if (uidsLidosRef.current.has(payload.uid)) {
      playErrorSound();
      toast.error("Caixa já bipada nesta separação");
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      return;
    }

    // ── Pré-fetch sem mutar status: precisa saber quantidade_interna pra checar excesso
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { data: pre } = await (supabase
      .from("etiquetas_qr") as any)
      .select("produto_master_id, produto_nome_snapshot, quantidade_interna, embalagem_nome, tipo_embalagem, lote_id, status")
      .eq("uid", payload.uid)
      .maybeSingle();

    const preEt = pre as
      | { produto_master_id: number; produto_nome_snapshot?: string | null; quantidade_interna?: number; embalagem_nome?: string | null; tipo_embalagem?: string | null; lote_id?: string | null; status?: string }
      | null;

    const qtyEtiqueta = Number(preEt?.quantidade_interna ?? payload.qty ?? 1);
    const tipoEmbEtq = preEt?.tipo_embalagem ?? null;
    const pidEstimado = Number(preEt?.produto_master_id ?? payload.pid ?? 0);
    const nomeEstimado = preEt?.produto_nome_snapshot || `Produto #${pidEstimado || "?"}`;

    // ── Excesso: se item da req achado e nova_qtd > pedido, pedir confirmação
    const target = matchBipItem(items, pidEstimado || null, nomeEstimado);
    // Regra universal: pedido bate com tipo da etiqueta → +1; senão → +qty_interna
    const qtyEstimada = calcularIncrementoBip(target?.unidade_medida, tipoEmbEtq, qtyEtiqueta);
    if (target) {
      // Base do acumulador autoritativo (não de `aplicados` stale).
      const baseAtual = enviadaAcumRef.current.get(target.id) ?? Number(target.quantidade_enviada || 0);
      const novaQtdPrev = baseAtual + qtyEstimada;
      if (novaQtdPrev > target.quantidade) {
        const sobra = novaQtdPrev - target.quantidade;
        const confirmed = await new Promise<boolean>((resolve) => {
          setExcesso({
            open: true,
            produtoNome: target.produto_nome,
            pedidoQtd: target.quantidade,
            jaEnviado: baseAtual,
            etiquetaQtd: qtyEstimada,
            sobra,
            resolve,
          });
        });
        if (!confirmed) {
          // Não chamou RPC ainda — etiqueta segue intacta no banco
          return;
        }
      }
    }

    // ── RPC = source of truth de validação
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const { data: rpcRaw, error: rpcErr } = await (supabase.rpc as any)("bipar_etiqueta", {
      p_uid: payload.uid,
      p_etapa: "separacao",
      p_contexto: {
        referencia_tipo: "requisicao",
        referencia_id: String(requisicaoId),
        payload,
      },
    });
    if (rpcErr) {
      playErrorSound();
      toast.error(`Falha no bip: ${rpcErr.message}`);
      return;
    }
    const result = rpcRaw as {
      ok: boolean;
      erro?: string;
      etiqueta?: { produto_master_id: number; produto_nome_snapshot?: string | null; lote_id?: string | null; quantidade_interna?: number; embalagem_nome?: string | null; tipo_embalagem?: string | null; separada_at?: string | null };
      alertas?: string[];
    };
    if (!result?.ok || !result.etiqueta) {
      // Caso especial: ja separada → verificar se é na MESMA req (bloqueia) ou em outra (transfere)
      const erroLower = (result?.erro || "").toLowerCase();
      const isJaSeparada = erroLower.includes('"separada"') || erroLower.includes("separada");
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      const etSep = result?.etiqueta as any;
      if (isJaSeparada) {
        // Descobre em qual requisição a etiqueta está separada (evento mais recente)
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const { data: evRaw } = await (supabase.from("etiquetas_qr_eventos") as any)
          .select("referencia_id")
          .eq("etiqueta_uid", payload.uid)
          .eq("etapa", "separacao")
          .order("created_at", { ascending: false })
          .limit(1)
          .maybeSingle();
        const refSeparada = (evRaw as { referencia_id?: string | null } | null)?.referencia_id ?? null;

        // Já separada NESTA requisição → idempotência, não conta de novo
        if (refSeparada != null && refSeparada === String(requisicaoId)) {
          playErrorSound();
          toast.error("Caixa já bipada nesta requisição");
          if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
          return;
        }
        // Separada em OUTRA requisição → transfere automático pra esta
        await executarTransferencia(payload.uid, etSep?.produto_nome_snapshot || nomeEstimado, payload);
        return;
      }
      playErrorSound();
      toast.error(formatBipError(result?.erro, "separacao", result?.etiqueta));
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
      return;
    }
    (result.alertas ?? []).forEach((a) => {
      playWarningSound();
      toast.warning(a);
    });

    const scannedPid = result.etiqueta.produto_master_id;
    const qtyEtiquetaReal = Number(result.etiqueta.quantidade_interna ?? payload.qty ?? 1);
    const scannedLote = result.etiqueta.lote_id ?? null;
    const scannedEmb = result.etiqueta.embalagem_nome ?? preEt?.embalagem_nome ?? null;
    const scannedNome = result.etiqueta.produto_nome_snapshot || nomeEstimado;
    // Regra universal: pedido bate com tipo da etiqueta → +1, senão → +qty real
    const scannedTipoEmb = result.etiqueta.tipo_embalagem ?? tipoEmbEtq;

    // Casagem robusta: masterId → fallback por nome normalizado. Blinda contra
    // masterId ausente no front (causa do "bip não preenche / fica 0/N").
    const targetReal = matchBipItem(items, scannedPid, scannedNome);
    if (!targetReal) {
      // NÃO engole: a RPC já transicionou a etiqueta no banco. Dá feedback claro
      // e registra como "extra" VISÍVEL (operador confere o pedido) — antes isso
      // sumia silenciosamente e o re-bip acusava "já lido" sem nada preenchido.
      uidsLidosRef.current.add(payload.uid);
      playWarningSound();
      if (navigator.vibrate) navigator.vibrate([60, 40, 60]);
      const incrementoExtra = calcularIncrementoBip(null, scannedTipoEmb, qtyEtiquetaReal);
      toast.warning(`${scannedNome}: não está nesta requisição — bip registrado como extra`);
      setAplicados((prev) => [
        {
          itemId: -1,
          produtoNome: `${scannedNome} (fora da lista)`,
          uid: payload.uid,
          qty: incrementoExtra,
          embalagem: scannedEmb,
          tipoEmbalagem: scannedTipoEmb,
          qtyInterna: qtyEtiquetaReal,
          loteId: scannedLote,
          bipadoAt: Date.now(),
        },
        ...prev,
      ]);
      return;
    }

    // Acumulador AUTORITATIVO — base do Map seedado, nunca de estado stale.
    const { incremento: scannedQty, nova: novaQtdNum } = computeNovaQtd(
      enviadaAcumRef.current, targetReal, scannedTipoEmb, qtyEtiquetaReal,
    );
    enviadaAcumRef.current.set(targetReal.id, novaQtdNum);

    // Selected batches sempre rastreia a qty FISICA da etiqueta (pro estoque por lote
    // ficar correto independente de unidade do pedido — lote conta unidades reais).
    const batchesNovo = accumBatches(batchesAcumRef.current.get(targetReal.id), scannedLote, qtyEtiquetaReal);
    batchesAcumRef.current.set(targetReal.id, batchesNovo);

    try {
      await onApply(targetReal.id, String(novaQtdNum), Object.keys(batchesNovo).length ? batchesNovo : undefined);
    } catch (e) {
      // Rollback do acumulador pra não divergir do DB (próximo bip recomeça certo).
      enviadaAcumRef.current.set(targetReal.id, novaQtdNum - scannedQty);
      playErrorSound();
      toast.error(`Erro ao salvar: ${(e as Error).message}`);
      return;
    }

    playSuccessSound();
    if (navigator.vibrate) navigator.vibrate(80);
    // Toast mostra "+1 caixa" usando o TIPO da etiqueta (caixa/saco/balde) — nunca "un"
    const tipoLabel = (scannedTipoEmb || targetReal.unidade_medida || 'cx').toLowerCase();
    toast.success(`${scannedNome} +${scannedQty} ${tipoLabel}`);

    setAplicados((prev) => [
      {
        itemId: targetReal.id,
        produtoNome: targetReal.produto_nome,
        uid: payload.uid,
        qty: scannedQty,
        embalagem: scannedEmb,
        tipoEmbalagem: scannedTipoEmb,
        qtyInterna: qtyEtiquetaReal,
        loteId: scannedLote,
        bipadoAt: Date.now(),
      },
      ...prev,
    ]);
    uidsLidosRef.current.add(payload.uid);
  };

  // Wrapper SERIAL: encadeia cada bip no mutex pra que o read-modify-write do
  // acumulador seja atômico. Eventos de scan chegam em ticks separados, então a
  // reatribuição síncrona de processingRef.current garante ordem (sem race).
  const handleBip = (payload: ScannedPayload) => {
    const run = processingRef.current.then(() => handleBipInner(payload)).catch(() => undefined);
    processingRef.current = run;
    return run;
  };

  const scanner = useEtiquetaScanner({
    enabled: isOpen,
    onScan: handleBip,
    onInvalid: () => {
      toast.error("QR ilegível");
    },
    onDuplicate: () => {
      playErrorSound();
      toast.error("Esta etiqueta já foi bipada");
      if (navigator.vibrate) navigator.vibrate([200, 100, 200]);
    },
    cameraElementId: "picking-bip-camera",
    initialMode: defaultMode,
  });

  // Progresso por item — caixas bipadas + un acumuladas
  const progressoPorItem = useMemo(() => {
    return items.map((item) => {
      const bipsItem = aplicados.filter((a) => a.itemId === item.id);
      const caixas = bipsItem.length;
      // totalUn vem do que foi efetivamente GRAVADO (onApply atualiza
      // quantidade_enviada). Fonte única e reativa — evita soma dupla com
      // `aplicados` e divergência quando o bip cobre N unidades por etiqueta.
      const totalUn = Number(item.quantidade_enviada || 0) || 0;
      const pedidoUn = item.quantidade || 0;
      const pct = pedidoUn > 0 ? Math.min(100, Math.round((totalUn / pedidoUn) * 100)) : 0;
      const status: "vazio" | "parcial" | "completo" | "excesso" =
        totalUn === 0 ? "vazio"
          : totalUn > pedidoUn ? "excesso"
          : totalUn >= pedidoUn ? "completo"
          : "parcial";
      return { item, caixas, totalUn, pedidoUn, pct, status };
    });
  }, [items, aplicados]);

  const stats = useMemo(() => {
    const completos = progressoPorItem.filter((p) => p.status === "completo" || p.status === "excesso").length;
    const totalUnSolicitado = progressoPorItem.reduce((acc, p) => acc + p.pedidoUn, 0);
    const totalUnEnviado = progressoPorItem.reduce((acc, p) => acc + p.totalUn, 0);
    const totalCaixas = aplicados.length;
    return {
      completos,
      itensTotais: items.length,
      bipsAplicados: aplicados.length,
      totalCaixas,
      totalUnSolicitado,
      totalUnEnviado,
    };
  }, [items, aplicados, progressoPorItem]);

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent
        data-mia-modal="separar-com-bip"
        className="max-w-[100vw] sm:max-w-[98vw] w-full h-[100dvh] sm:h-[95vh] p-0 flex flex-col overflow-hidden bg-background sm:rounded-[1.5rem] rounded-none"
        onPointerDownOutside={(e) => e.preventDefault()}
        onInteractOutside={(e) => e.preventDefault()}
      >
        {/* Header */}
        <div className="flex items-center justify-between gap-2 px-3 sm:px-5 py-2 sm:py-3 flex-shrink-0 border-b border-border/50">
          <div className="flex items-center gap-2 sm:gap-3 min-w-0 flex-1">
            <Button data-mia-action="on-close" variant="ghost" size="icon" onClick={onClose} className="rounded-2xl hover:bg-[#57715B]/10 h-11 w-11 flex-shrink-0">
              <ArrowLeft className="w-5 h-5 text-[#57715B]" />
            </Button>
            <div className="h-10 w-10 rounded-2xl bg-[#57715B]/10 flex items-center justify-center flex-shrink-0">
              <ScanBarcode className="h-5 w-5 text-[#57715B]" />
            </div>
            <div className="min-w-0 flex-1">
              <DialogTitle className="text-base sm:text-lg font-bold text-[#57715B] dark:text-[#E6DCCF] truncate">
                Separar com bip
              </DialogTitle>
              <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
                Aponte o leitor pra cada caixa que vai entrar no pedido
              </p>
            </div>
          </div>
          <div className="flex p-1 rounded-xl bg-muted/50 dark:bg-zinc-800 flex-shrink-0">
            <button
              onClick={() => scanner.setScanMode("bluetooth")}
              aria-label="Scanner Bluetooth"
              className={cn(
                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                scanner.scanMode === "bluetooth"
                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
                  : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Bluetooth className="h-4 w-4" /> <span className="hidden sm:inline">Scanner</span>
            </button>
            <button
              onClick={() => scanner.setScanMode("camera")}
              aria-label="Scanner por câmera"
              className={cn(
                "min-h-[44px] min-w-[44px] px-3 sm:px-4 py-2 text-sm font-medium rounded-lg flex items-center gap-2 transition-all",
                scanner.scanMode === "camera"
                  ? "bg-white dark:bg-zinc-700 text-[#57715B] shadow-sm"
                  : "text-muted-foreground hover:text-foreground"
              )}
            >
              <Camera className="h-4 w-4" /> <span className="hidden sm:inline">Câmera</span>
            </button>
          </div>
        </div>

        {/* Stats — caixas + qty lado-a-lado.
            Label "Enviado" eh generica porque a requisicao pode ter items em unidades
            diferentes (caixa + kg). Detalhe por unidade fica no ItemProgress de cada item. */}
        <div className="px-3 sm:px-5 py-3 flex-shrink-0 border-b border-border/50 grid grid-cols-2 sm:grid-cols-4 gap-2 sm:gap-3">
          <Stat label="Itens completos" value={`${stats.completos}/${stats.itensTotais}`} />
          <Stat label="Bipados" value={String(stats.totalCaixas)} icon={<Boxes className="w-3 h-3" />} />
          <Stat label="Enviado" value={`${stats.totalUnEnviado}/${stats.totalUnSolicitado}`} />
          <Stat label="Bips" value={String(stats.bipsAplicados)} />
        </div>

        {/* Scanner input invisível (Bluetooth) */}
        {scanner.scanMode === "bluetooth" && <input {...scanner.inputProps} />}

        {/* Body */}
        <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
          {scanner.scanMode === "camera" ? (
            <div className="w-full md:w-[260px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 bg-black overflow-hidden relative">
              <div id={scanner.cameraElementId} className="w-full h-[200px] md:h-full" />
              <CameraScannerStatus
                starting={scanner.cameraStarting}
                error={scanner.cameraError}
                onRetry={scanner.retryCamera}
              />
            </div>
          ) : (
            <div
              className="w-full md:w-[200px] flex-shrink-0 border-b md:border-b-0 md:border-r border-border/50 flex flex-col items-center justify-center p-5 cursor-pointer"
              onClick={() => document.querySelector<HTMLInputElement>("input[autofocus]")?.focus()}
            >
              <div className="w-20 h-20 rounded-full bg-[#57715B]/10 flex items-center justify-center relative">
                <Bluetooth className="w-9 h-9 text-[#57715B]" />
                <div className="absolute inset-0 rounded-full border-[3px] border-[#57715B]/20 border-t-[#57715B] animate-spin" style={{ animationDuration: "3s" }} />
              </div>
              <h3 className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF] mt-4">Aguardando bip…</h3>
              <p className="text-[11px] text-muted-foreground text-center mt-1">
                Leitor Bluetooth aponta na caixa e dispara
              </p>
            </div>
          )}

          <div className="flex-1 flex flex-col overflow-hidden">
            <ScrollArea className="flex-1">
              <div className="p-2.5 space-y-3">
                {/* Progresso por item */}
                {progressoPorItem.length > 0 && (
                  <div className="space-y-1.5">
                    <p className="text-[10px] uppercase tracking-widest text-muted-foreground font-bold px-1">
                      Progresso por item
                    </p>
                    {progressoPorItem.map((p) => (
                      <ItemProgress key={p.item.id} progress={p} />
                    ))}
                  </div>
                )}

                {/* Cards de bip */}
                <div className="space-y-2 pt-2 border-t border-border/30">
                  <p className="text-[10px] uppercase tracking-widest text-muted-foreground font-bold px-1">
                    Caixas bipadas ({aplicados.length})
                  </p>
                  {aplicados.length === 0 ? (
                    <div className="flex flex-col items-center justify-center py-10 text-muted-foreground/40">
                      <Package className="w-12 h-12 mb-2" />
                      <p className="text-sm font-semibold">Nenhuma caixa bipada ainda</p>
                      <p className="text-[11px] mt-1 text-center max-w-[260px]">
                        Cada bip = 1 caixa. Total de unidades soma a partir do tamanho da etiqueta.
                      </p>
                    </div>
                  ) : (
                    aplicados.map((b) => <BipCard key={b.uid} bip={b} />)
                  )}
                </div>
              </div>
            </ScrollArea>
          </div>
        </div>

        {/* Footer */}
        <div
          className="px-3 sm:px-5 py-3 border-t border-border/50 flex items-center justify-between gap-2 flex-shrink-0"
          style={{ paddingBottom: "calc(env(safe-area-inset-bottom) + 12px)" }}
        >
          <p className="text-[11px] sm:text-xs text-muted-foreground truncate">
            {stats.bipsAplicados === 0
              ? "Pronto pra bipar."
              : `${stats.totalCaixas} bip(s) · ${stats.totalUnEnviado} aplicado(s)`}
          </p>
          <Button data-mia-action="on-close" onClick={onClose} className="h-11 flex-shrink-0">Concluir</Button>
        </div>
      </DialogContent>

      {/* AlertDialog de excesso */}
      <AlertDialog
        open={excesso.open}
        onOpenChange={(open) => {
          if (!open && excesso.resolve) {
            excesso.resolve(false);
            setExcesso((s) => ({ ...s, open: false, resolve: undefined }));
          }
        }}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle className="flex items-center gap-2 text-amber-700">
              <AlertTriangle className="w-5 h-5" /> Etiqueta excede o pedido
            </AlertDialogTitle>
            <AlertDialogDescription asChild>
              <div className="space-y-2 text-sm pt-2">
                <p className="font-semibold text-foreground">{excesso.produtoNome}</p>
                <div className="grid grid-cols-2 gap-2 text-xs bg-muted/40 rounded-lg p-3">
                  <div>
                    <p className="uppercase tracking-wider text-muted-foreground font-bold text-[10px]">Pedido</p>
                    <p className="font-bold tabular-nums">{excesso.pedidoQtd} un</p>
                  </div>
                  <div>
                    <p className="uppercase tracking-wider text-muted-foreground font-bold text-[10px]">Já enviado</p>
                    <p className="font-bold tabular-nums">{excesso.jaEnviado} un</p>
                  </div>
                  <div>
                    <p className="uppercase tracking-wider text-muted-foreground font-bold text-[10px]">Esta etiqueta</p>
                    <p className="font-bold tabular-nums">+{excesso.etiquetaQtd} un</p>
                  </div>
                  <div>
                    <p className="uppercase tracking-wider text-amber-700 font-bold text-[10px]">Sobrará</p>
                    <p className="font-bold tabular-nums text-amber-700">+{excesso.sobra} un</p>
                  </div>
                </div>
                <p className="text-muted-foreground">
                  Confirmar mesmo assim envia a caixa inteira (sobrará saldo extra na loja).
                </p>
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel
              onClick={() => {
                excesso.resolve?.(false);
                setExcesso((s) => ({ ...s, open: false, resolve: undefined }));
              }}
            >
              Cancelar bip
            </AlertDialogCancel>
            <AlertDialogAction
              className="bg-amber-600 hover:bg-amber-700"
              onClick={() => {
                excesso.resolve?.(true);
                setExcesso((s) => ({ ...s, open: false, resolve: undefined }));
              }}
            >
              Confirmar excesso
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

    </Dialog>
  );
}

function Stat({ label, value, icon }: { label: string; value: string | number; icon?: React.ReactNode }) {
  return (
    <div className="text-center min-w-0">
      <p className="text-[9px] sm:text-[10px] uppercase tracking-widest text-muted-foreground font-bold truncate flex items-center gap-1 justify-center">
        {icon}{label}
      </p>
      <p className="text-xl sm:text-2xl font-black tabular-nums text-[#57715B]">{value}</p>
    </div>
  );
}

interface ProgressoItem {
  item: PickingBipItem;
  caixas: number;
  totalUn: number;
  pedidoUn: number;
  pct: number;
  status: "vazio" | "parcial" | "completo" | "excesso";
}

function ItemProgress({ progress }: { progress: ProgressoItem }) {
  const { item, caixas, totalUn, pedidoUn, pct, status } = progress;
  const bg = status === "completo" ? "bg-emerald-500"
    : status === "excesso" ? "bg-amber-500"
    : status === "parcial" ? "bg-[#57715B]"
    : "bg-zinc-300 dark:bg-zinc-700";
  const ring = status === "completo" ? "border-emerald-500/40 bg-emerald-500/5"
    : status === "excesso" ? "border-amber-500/40 bg-amber-500/5"
    : status === "parcial" ? "border-[#57715B]/30 bg-[#57715B]/5"
    : "border-border/50";
  return (
    <div className={cn("rounded-xl border-2 p-2.5", ring)}>
      <div className="flex items-center justify-between gap-2 mb-1.5">
        <p className="text-sm font-semibold leading-tight truncate flex-1 min-w-0">{item.produto_nome}</p>
        <div className="flex items-center gap-1.5 text-[11px] flex-shrink-0">
          <span className={cn(
            "inline-flex items-center gap-0.5 font-bold tabular-nums",
            status === "completo" ? "text-emerald-700" : status === "excesso" ? "text-amber-700" : "text-foreground"
          )}>
            <Boxes className="w-3 h-3" />{caixas}
          </span>
          <span className="text-muted-foreground">·</span>
          <span className={cn(
            "font-bold tabular-nums",
            status === "completo" ? "text-emerald-700" : status === "excesso" ? "text-amber-700" : "text-foreground"
          )}>
            {totalUn}/{pedidoUn} {(item.unidade_medida || 'un').toLowerCase()}
          </span>
        </div>
      </div>
      <div className="w-full h-1.5 bg-zinc-100 dark:bg-zinc-800 rounded-full overflow-hidden">
        <div className={cn("h-full rounded-full transition-all duration-500", bg)} style={{ width: `${pct}%` }} />
      </div>
    </div>
  );
}

function BipCard({ bip }: { bip: BipApplied }) {
  return (
    <div className="rounded-2xl bg-white dark:bg-zinc-900 border border-emerald-500/30 p-3 flex items-start gap-3">
      <div className="h-9 w-9 rounded-xl bg-emerald-500/10 flex items-center justify-center flex-shrink-0">
        <CheckCircle2 className="h-4 w-4 text-emerald-600" />
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-sm font-semibold leading-tight truncate">{bip.produtoNome}</p>
        <div className="flex items-center gap-3 text-[10px] text-muted-foreground mt-1 flex-wrap">
          <span className="font-bold text-emerald-700">
            +1 {bip.tipoEmbalagem || "caixa"}{bip.qtyInterna > 1 ? ` (${bip.qtyInterna} ${bip.embalagem || 'un'})` : ""}
          </span>
          {bip.loteId && <span className="font-mono">Lote {bip.loteId.slice(0, 8)}</span>}
          <span className="font-mono truncate">UID {bip.uid}</span>
        </div>
      </div>
    </div>
  );
}

